"""Landmark silhouettes for the city markers, drawn with content/cities/draw.py in a 100 x 100 box standing on y = 96.
Each is one path; scripts/build_cities.py writes them into data/cities.json and the page turns them into symbols."""
from draw import P, R, C, D, A, O, B, bud, band, teeth, eave


def stairs(x, w, y0, y1):
    """a stair up the front of a pyramid or ziggurat: slots with treads between, so the steps don't split the shape"""
    out, y = [], y0
    while y + 2.6 <= y1:
        out.append(R(x, y, w, 2.6, True)); y += 5
    return ''.join(out)

ICONS = {}


def I(name, *parts):
    ICONS[name] = ''.join(parts)


